// NODO TORICO (p,q) = (3,4), ispessito in un tubo.
// La curva centrale sta sul toro di raggi R = 1 e r = C: compie p giri attorno
// all'asse e q giri attorno al tubo prima di richiudersi. p e q sono primi fra
// loro, quindi e' UN solo anello chiuso, e con entrambi > 1 e' un vero nodo.
//
// B = raggio del tubo. La curva si avvicina a se stessa fino a 0.307, quindi
// oltre B = 0.153 i rami si compenetrano.
// C = raggio r del toro di supporto.
//
// FRAME DAL TORO, NON DI FRENET.
// Il frame di Frenet ruota attorno alla curva in modo brusco dove la curvatura
// e' minima: su questo nodo la normale saltava di 25 gradi a u = pi/4, 3pi/4,
// 5pi/4, 7pi/4 (i minimi di curvatura, 0.0439), e il tubo mostrava li' quattro
// STROZZATURE -- torsioni improvvise della sezione, non difetti geometrici.
// Qui la normale si prende invece dalla SUPERFICIE DEL TORO su cui la curva
// vive: e' definita ovunque, non dipende dalla derivata seconda e non ha nulla
// da cui scattare. Salto massimo misurato: 0.9 gradi contro 24.74.

float pw = 3.0;          // giri attorno all'asse
float qw = 4.0;          // giri attorno al tubo
float R  = 1.0;
float rr = C;            // raggio del toro di supporto

float ang = pw * u;      // posizione angolare attorno all'asse
float rad = R + rr * cos(qw * u);

// Punto sulla curva
vec3 P0 = vec3(rad * cos(ang), rad * sin(ang), rr * sin(qw * u));

// Tangente analitica (derivata esatta, niente differenze finite)
vec3 T = vec3(
    -rr * qw * sin(qw * u) * cos(ang) - rad * pw * sin(ang),
    -rr * qw * sin(qw * u) * sin(ang) + rad * pw * cos(ang),
     rr * qw * cos(qw * u));
T = normalize(T);

// Normale della superficie del toro nel punto: dal centro del tubo verso P0.
// Il centro del tubo e' il punto del cerchio guida alla stessa posizione
// angolare, a distanza R dall'asse.
vec3 axis   = vec3(cos(ang), sin(ang), 0.0);
vec3 center = R * axis;
vec3 Nn     = normalize(P0 - center);

// Ortogonalizza rispetto alla tangente (Gram-Schmidt) e completa il frame
Nn = normalize(Nn - dot(Nn, T) * T);
vec3 Bn = cross(T, Nn);

// Sezione circolare di raggio B nel piano normale
return vec4(P0 + B * (cos(v) * Nn + sin(v) * Bn), 0.0);
